media:
flowchart LR
    D["Dialled<br/>number,<br/>checked in<br/>this order"] --> X{"What<br/>is it?"}
    X -- "911 or 933" --> SOS["Emergency lane,<br/>see below"]
    X -- "777" --> E["Echo test"]
    X -- "999" --> G["Page every phone,<br/>auto-answer"]
    X -- "980 to 989" --> Z["Page a zone"]
    X -- "440" --> T["Test tone"]
    X -- "888" --> C["Meet-me conference,<br/>up to 4 legs mixed<br/>on the board"]
    X -- "997" --> MP["Multicast page"]
    X -- "555" --> M["3CX anchor bridge"]
    X -- "796" --> VR["Voicemail retrieval"]
    X -- "700 to 709" --> K["Park orbit,<br/>hold music, rings<br/>the parker back<br/>after 90 s"]
    X -- "*8, **ext" --> PU["Call pickup"]
    X -- "a group<br/>extension" --> RG["Ring group<br/>or hunt group"]
    X -- "a dial-plan<br/>rule" --> O["Group, page, park,<br/>outside line"]
    X -- "an extension" --> R["Forward always,<br/>DND (480),<br/>or ring the phone"]
    R -- "no answer" --> VM["Forward on<br/>no answer,<br/>or voicemail"]

    classDef media stroke-width:3px;
    class SOS,E,T,C,MP,M,VR,K,VM media;
    classDef start fill:#e3edf4,stroke:#3f6f8c,stroke-width:1px;
    class D,X start;
    classDef sos fill:#fbe6e3,stroke:#b3362a,stroke-width:3px,color:#4a1410;
    class SOS sos;
